# Exact coordinates and diagonal alignments among all colored cells
pts={'1':[(2,2),(4,14),(10,10),(17,9)],'6':[(4,4),(6,6),(7,14),(15,2)]}
for color, p in pts.items():
 print(color)
 for i,(r,c) in enumerate(p):
  for rr,cc in p[i+1:]:
   if abs(r-rr)==abs(c-cc): print((r,c),'->',(rr,cc),'slope', (rr-r)//abs(rr-r) if r!=rr else 0)
for col1,p in pts.items():
 for r,c in p:
  for col2,q in pts.items():
   if col1==col2: continue
   for rr,cc in q:
    if abs(r-rr)==abs(c-cc): print('mixed',col1,(r,c),col2,(rr,cc))
